def exist(board, word):
    rows, cols = len(board), len(board[0])
    n = len(word)
    visited = [[False] * cols for _ in range(rows)]

    def dfs(i, j, k):
        if k == n:
            return True
        if i < 0 or i >= rows or j < 0 or j >= cols or visited[i][j] or board[i][j] != word[k]:
            return False
        visited[i][j] = True                                                # track visited cells using a SEPARATE grid, rather than modifying board
        found = (dfs(i + 1, j, k + 1) or dfs(i - 1, j, k + 1) or
                 dfs(i, j + 1, k + 1) or dfs(i, j - 1, k + 1))
        visited[i][j] = False                                                # backtrack: this cell is free again for other paths
        return found

    for i in range(rows):
        for j in range(cols):
            if dfs(i, j, 0):
                return True
    return False


if __name__ == "__main__":
    board = [['A','B','C','E'],['S','F','C','S'],['A','D','E','E']]
    print(exist(board, 'SEE'))

