import java.util.*;

public class Main {
    boolean exist(char[][] board, String word) {
        int rows = board.length, cols = board[0].length;
        boolean[][] visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (dfs(board, word, i, j, 0, visited)) return true;
            }
        }
        return false;
    }

    boolean dfs(char[][] board, String word, int i, int j, int k, boolean[][] visited) {
        if (k == word.length()) return true;
        int rows = board.length, cols = board[0].length;
        if (i < 0 || i >= rows || j < 0 || j >= cols || visited[i][j] || board[i][j] != word.charAt(k)) return false;
        visited[i][j] = true;                                                     // track visited cells using a SEPARATE grid, rather than modifying board
        boolean found = dfs(board, word, i + 1, j, k + 1, visited) ||
                         dfs(board, word, i - 1, j, k + 1, visited) ||
                         dfs(board, word, i, j + 1, k + 1, visited) ||
                         dfs(board, word, i, j - 1, k + 1, visited);
        visited[i][j] = false;                                                     // backtrack: this cell is free again for other paths
        return found;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        char[][] board = {{'A','B','C','E'}, {'S','F','C','S'}, {'A','D','E','E'}};
        System.out.println(solution.exist(board, "SEE"));
    }
}

